import React from "react";
import {
  Card,
  CardContent,
  Typography,
  Stack,
  IconButton,
  Box,
} from "@mui/material";
import DeleteIcon from "@mui/icons-material/Delete";
import EditIcon from "@mui/icons-material/Edit";

const EventList = ({ events, onDelete, onEdit }) => {
  return (
    <Stack spacing={3}>
      {events.map((event) => (
        <Card
          key={event._id}
          sx={{
            backdropFilter: "blur(12px)",
            background: "rgba(255, 255, 255, 0.05)",
            border: "1px solid rgba(255,255,255,0.1)",
            borderRadius: "20px",
            padding: 1,
            transition: "0.3s",
            cursor: "pointer",
            "&:hover": {
              transform: "translateY(-5px)",
              boxShadow: "0 10px 30px rgba(0,0,0,0.35)",
              background: "rgba(255, 255, 255, 0.1)",
            },
          }}
        >
          <CardContent>
            <Box
              display="flex"
              justifyContent="space-between"
              alignItems="flex-start"
            >
              {/* LEFT SECTION */}
              <Box>
                <Typography
                  variant="h6"
                  sx={{
                    fontWeight: 700,
                    fontSize: "1.3rem",
                    mb: 1,
                    letterSpacing: "0.5px",
                  }}
                >
                  {event.title}
                </Typography>

                <Typography
                  variant="body2"
                  sx={{ opacity: 0.8, fontSize: "0.9rem" }}
                >
                  📅 {event.date} • {event.category}
                </Typography>

                <Typography sx={{ mt: 1.3, lineHeight: 1.5 }}>
                  {event.description}
                </Typography>

                {event.location && (
                  <Typography
                    variant="caption"
                    sx={{ display: "block", mt: 0.5, opacity: 0.7 }}
                  >
                    📍 {event.location}
                  </Typography>
                )}
              </Box>

              {/* RIGHT SECTION (ICONS) */}
              <Box>
                <IconButton color="primary" onClick={() => onEdit(event)}>
                  <EditIcon />
                </IconButton>

                <IconButton
                  color="error"
                  onClick={() => onDelete(event._id)}
                  sx={{ ml: 1 }}
                >
                  <DeleteIcon />
                </IconButton>
              </Box>
            </Box>
          </CardContent>
        </Card>
      ))}
    </Stack>
  );
};

export default EventList;
